/* CSS PART 1 OF 2 */

/* Fictional workshop: Creative Skills Studio */
:root {
  --color-primary: #315c52;
  --color-accent: #e9b873;
  --color-background: #f8f6f0;
  --color-text: #28332f;
  --color-white: #ffffff;
  --content-width: 1120px;
  --radius: 12px;
}

body {
  margin: 0;
  font-family: Arial, sans-serif;
  background: var(--color-background);
  color: var(--color-text);
  line-height: 1.6;
}

.site-header {
  padding: 20px 5%;
  background: var(--color-white);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.hero {
  max-width: var(--content-width);
  margin: 0 auto;
  padding: 80px 24px;
  text-align: center;
  background: var(--color-background);
}
